255	        String identityKey = owner.getIdentityKey();
256	        // Owners can only share an identity key when they share a (normalized) telephone, so it is
257	        // enough to compare against the owners already stored with the same telephone.
258	        return ownerRepository.findByTelephone(owner.getTelephone()).stream()
259	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
260	    }
