262	    /**
263	     * Find an existing owner that this (not yet persisted) owner soft-matches: one sharing its last
264	     * name (ignoring case) and postcode but carrying a different telephone, so it is not a hard
265	     * identity-key duplicate. Returns the matching owner's id (the lowest when several match), or
266	     * {@code null} when the owner has no postcode or nothing matches.
267	     */
268	    @Override
269	    @Transactional(readOnly = true)
270	    public Integer findPossibleDuplicateOwnerId(Owner owner) throws DataAccessException {
271	        if (owner.getPostcode() == null) {
272	            return null;
273	        }
274	        return ownerRepository.findByLastNameIgnoreCase(owner.getLastName()).stream()
275	            .filter(existing -> owner.getPostcode().equals(existing.getPostcode()))
276	            .filter(existing -> !Objects.equals(owner.getTelephone(), existing.getTelephone()))
277	            .map(Owner::getId)
278	            .min(Integer::compareTo)
279	            .orElse(null);
280	    }
